use silo_zec_core::SiloZecCore;use zcash_client_backend::proto::service::{compact_tx_streamer_client::CompactTxStreamerClient,Empty,BlockId,BlockRange};use zcash_protocol::consensus::{BranchId,BlockHeight,TEST_NETWORK};use rand::TryRng;
#[tokio::main] async fn main()->Result<(),Box<dyn std::error::Error>>{
 let url="https://testnet.zec.rocks";let tls=tonic::transport::ClientTlsConfig::new().with_webpki_roots();let channel=tonic::transport::Endpoint::from_static("https://testnet.zec.rocks").tls_config(tls)?.connect().await?;let mut client=CompactTxStreamerClient::new(channel);
 let info=client.get_lightd_info(Empty{}).await?.into_inner();let tip=u32::try_from(info.block_height)?;let branch=format!("{:08x}",u32::from(BranchId::for_height(&TEST_NETWORK,BlockHeight::from_u32(tip))));if info.chain_name!="test"||!info.consensus_branch_id.eq_ignore_ascii_case(&branch){return Err("Testnet consensus not verified".into())}
 if tip<4_465_026{return Err("Node is before the tested NU7 epoch".into())}let birthday=tip-20;let prior=client.get_tree_state(BlockId{height:(birthday-1) as u64,hash:vec![]}).await?.into_inner();let mut stream=client.get_block_range(BlockRange{start:Some(BlockId{height:birthday as u64,hash:vec![]}),end:Some(BlockId{height:tip as u64,hash:vec![]}),..Default::default()}).await?.into_inner();let mut blocks=vec![];while let Some(block)=stream.message().await?{if blocks.len()>=21{return Err("Block range exceeded bound".into())}blocks.push(block);}if blocks.len()!=21{return Err("Incomplete block range".into())}
 let mut entropy=[0u8;32];rand::rngs::SysRng.try_fill_bytes(&mut entropy)?;let mnemonic=bip0039::Mnemonic::<bip0039::English>::from_entropy(entropy)?;entropy.fill(0);let phrase=mnemonic.phrase();let mut prior_bytes=vec![];prost::Message::encode(&prior,&mut prior_bytes)?;
 let mut wallet=SiloZecCore::create("test",phrase,Some(prior_bytes.clone())).map_err(|e|format!("{e:?}"))?;let address=wallet.orchard_address().map_err(|e|format!("{e:?}"))?;wallet.scan_for_test(prior.clone(),blocks.clone()).map_err(|e|format!("{e:?}"))?;let db=wallet.to_bytes().map_err(|e|format!("{e:?}"))?;let mut reopened=SiloZecCore::open("test",&db).map_err(|e|format!("{e:?}"))?;let mut restored=SiloZecCore::create("test",phrase,Some(prior_bytes)).map_err(|e|format!("{e:?}"))?;restored.scan_for_test(prior,blocks).map_err(|e|format!("{e:?}"))?;
 println!("{}",serde_json::json!({"kind":"native-readonly-testnet","node":url,"tip":tip,"serverBranch":info.consensus_branch_id,"engineBranch":branch,"birthday":birthday,"databaseBytes":db.len(),"summary":serde_json::from_str::<serde_json::Value>(&wallet.summary().map_err(|e|format!("{e:?}"))?)?,"cacheReopenSameAddress":reopened.orchard_address().map_err(|e|format!("{e:?}"))?==address,"seedRestoreSameAddress":restored.orchard_address().map_err(|e|format!("{e:?}"))?==address,"signed":false,"sent":false,"browserEvidence":false}));Ok(())}
